<template>
  <div class="premium-event-detail">
    <router-link v-if="!preview" class="detail-back" to="/public/events"><ConsumerIcon name="back" />赛事列表</router-link>
    <section class="premium-detail-hero">
      <img class="detail-image" :src="heroImage" alt="" @error="bannerFailed=true" />
      <div class="detail-heading"><div class="detail-pills"><span :class="{ cancelled:event.holdingStatus==='cancelled' }">{{ holdingText }}</span><span>{{ event.projectName || '运动赛事' }}</span><span>{{ phaseLabel(event.phase) }}</span></div><h1>{{ event.name }}</h1><p><ConsumerIcon name="pin"/>{{ event.location || '地点待公布' }}</p></div>
    </section>
    <div class="detail-key-facts"><div><ConsumerIcon name="calendar"/><span>比赛时间<strong>{{ showTime(event.startsAt) }}</strong></span></div><div><ConsumerIcon name="clock"/><span>报名截止<strong>{{ showTime(event.registrationClosesAt) }}</strong></span></div><div><ConsumerIcon name="team"/><span>主办组织<strong>{{ fees?.organizationName || '正在读取' }}</strong></span></div></div>
    <div class="premium-detail-layout">
      <main class="detail-main">
        <section class="detail-unit-section" id="event-projects"><div class="detail-section-head"><h2>选择比赛项目</h2><span>{{ registrationHint }}</span></div><p v-if="feeError" class="detail-read-error" role="alert">{{ feeError }}</p><p v-else-if="!fees" class="detail-muted">正在读取项目与费用。</p><p v-else-if="!fees.units.length" class="detail-muted">项目安排还未公布，请联系主办方。</p><article v-for="unit in fees?.units || []" :key="unit.unitId" class="detail-project"><div><h3>{{ unit.unitName }}</h3><p v-if="unit.payInstruction">{{ unit.payInstruction }}</p><p v-else>{{ unit.paymentMode==='free' ? '报名免费，仍需确认参赛资料和声明。' : '正式提交后，在报名详情查看付款安排。' }}</p></div><div class="project-signup"><strong>{{ priceText(unit) }}</strong><router-link v-if="!preview && canRegister && priceReady(unit)" class="btn primary" :to="{path:'/portal/registration/apply',query:{eventId:event.id,unitId:unit.unitId}}">选择项目<ConsumerIcon name="arrow"/></router-link><span v-else>{{ !priceReady(unit) ? '费用待公布' : registrationHint }}</span></div></article><p v-if="fees?.refundNote" class="detail-footnote">{{ fees.refundNote }}</p><p v-if="!canRegister" class="detail-status-note">{{ event.holdingStatus==='cancelled'?'赛事已取消。已有报名、退款及问题处理请到报名详情继续办理。':registrationHint+'。已有报名仍可查看进度。' }}</p></section>
        <section class="detail-material-section"><nav class="detail-tabs" aria-label="赛事资料"><button v-for="tab in availableTabs" :key="tab.key" type="button" :class="{active:activeTab===tab.key}" :aria-pressed="activeTab===tab.key" @click="activeTab=tab.key">{{ tab.label }}</button></nav><div v-if="activeTab==='info'" class="detail-info"><div><span>比赛时间</span><strong>{{ showTime(event.startsAt) }} — {{ showTime(event.endsAt) }}</strong></div><div><span>报名窗口</span><strong>{{ showTime(event.registrationOpensAt) }} — {{ showTime(event.registrationClosesAt) }}</strong></div><div><span>举办地点</span><strong>{{ event.location || '地点待公布' }}</strong></div><div><span>联系人</span><strong>{{ fees?.contactName || '未公布' }} {{ fees?.contactMethod }}</strong></div></div><template v-for="tab in materialTabs" :key="tab.key"><div v-if="activeTab===tab.key" class="detail-material"><p v-if="tab.text">{{ tab.text }}</p><el-image v-if="tab.fileId && media?.[tab.key]" :src="media[tab.key]" :preview-src-list="[media[tab.key]]" fit="contain" :alt="tab.label" class="detail-material-image" :hide-on-click-modal="true" /><p v-if="tab.fileId" class="detail-footnote">点击图片放大查看。报名时请认真阅读完整内容。</p></div></template></section>
        <p v-if="event.cancelReason" class="detail-cancel-reason">取消原因：{{ event.cancelReason }}</p>
      </main>
      <aside class="detail-aside"><section class="detail-plan"><span class="detail-eyebrow">参赛安排</span><h2>{{ registrationHint }}</h2><div class="detail-plan-line"><span>报名截止</span><strong>{{ showTime(event.registrationClosesAt) }}</strong></div><div class="detail-plan-line"><span>举办地点</span><strong>{{ event.location || '地点待公布' }}</strong></div><a v-if="canRegister" class="btn primary" href="#event-projects">选择比赛项目<ConsumerIcon name="arrow"/></a><router-link v-if="!preview" class="btn" to="/portal/registration">我的报名与进度</router-link><p>报名名单、资格与付款分别办理，以报名详情的实际状态为准。</p></section><section v-if="!preview" class="detail-ai"><img class="detail-ai-icon sport-assistant-mark sport-assistant-mark--card" src="/images/sports/assistant-orb-v2.webp" alt="" width="32" height="32" draggable="false"/><h3>查看参赛要求</h3><p>了解报名条件、费用和时间，并查看相关依据。</p><button class="btn" @click="openConsumerAi('请解释本场赛事的报名资格、费用和重要时间，并指出依据。')">询问规程<ConsumerIcon name="arrow"/></button></section><section class="detail-contact"><h3>联系主办方</h3><strong>{{ fees?.organizationName || '正在读取' }}</strong><p>{{ fees?.contactName }} {{ fees?.contactMethod || '暂未公开联系方式' }}</p><button v-if="!preview" class="detail-share" @click="copyLink">分享赛事链接<ConsumerIcon name="arrow"/></button></section></aside>
    </div>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { openConsumerAi } from '@/utils/consumerAi';
import ConsumerIcon from './ConsumerIcon.vue';
import { type EventCard, phaseLabel, showTime } from '@/api/sports/event';
import { paymentModeLabel } from '@/api/sports/finance';
import { registrationPriceReady, registrationPriceText } from '@/utils/registrationPrice';
export interface PublicUnitPrice {unitId:string;unitName:string;amount:number|null;paymentMode:string|null;payInstruction:string|null;}
export interface PublicFees {organizationName:string|null;contactName:string|null;contactMethod:string|null;refundNote:string;units:PublicUnitPrice[];}
const props=defineProps<{event:EventCard;fees?:PublicFees;feeError?:string;media?:Record<string,string>;preview?:boolean}>();
const bannerFailed=ref(false),activeTab=ref('info');
const banner=computed(()=>props.media?.banner||'');
const heroImage=computed(()=>banner.value&&!bannerFailed.value?banner.value:'/images/sports/badminton-hero-v1.webp');
watch(banner,()=>bannerFailed.value=false);
const canRegister=computed(()=>props.event.holdingStatus!=='cancelled'&&props.event.phase==='registration');
const registrationHint=computed(()=>props.event.holdingStatus==='cancelled'?'赛事已取消':canRegister.value?'报名正在进行':phaseLabel(props.event.phase));
const holdingText=computed(()=>props.event.holdingStatus==='cancelled'?'已取消':'正常举办');
const materialTabs=computed(()=>[{key:'rules',label:'竞赛规程',text:props.event.rulesText,fileId:props.event.rulesFileId},{key:'notice',label:'报名须知',text:props.event.noticeText,fileId:props.event.noticeFileId},{key:'declaration',label:'参赛声明',text:props.event.declarationText,fileId:props.event.declarationFileId},{key:'route',label:'场馆路线',text:props.event.routeText,fileId:props.event.routeFileId}].filter(tab=>tab.text||tab.fileId));
const availableTabs=computed(()=>[{key:'info',label:'赛事信息'},...materialTabs.value]);
watch(()=>props.event.id,()=>activeTab.value='info');
const priceReady=registrationPriceReady;
const priceText=registrationPriceText;
const copyLink=async()=>{try{await navigator.clipboard.writeText(location.origin+'/public/events/'+props.event.id);ElMessage.success('赛事链接已复制');}catch{ElMessage.warning('暂时无法复制，请复制浏览器中的赛事地址');}};
</script>
